function [r] = kpi_cp_upper(n, k, g)
%KPI_CP_UPPER  The upper bound of the probability R at confidence g: 1 with all successes; 1 - g' ^ (1/n) with none; else the R at which the
%   chance of k or fewer is 1 - g, by bisection.
%   length: 64
%   n: int (passed a whole number)
%   k: int (passed a whole number)
%   g: real[1] (passed a plain number)
%   returns r: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    r = 0;
    r = 1;
    if ((n > 0) && (k <= 0))
        h__660 = log((1 - g));
        if ~isreal(h__660), h__660 = NaN; end
        r = (1 - exp((h__660 / n)));
    elseif (k < n)
        lo = 0;
        hi = 1;
        for it = (0):((60) - 1)
            mid = (0.5 * (lo + hi));
            if (asils.models.kpistats.kpi_binomial_tail(n, k, mid, false) > (1 - g))
                lo = mid;
            else
                hi = mid;
            end
        end
        r = (0.5 * (lo + hi));
    end
end
